+    /**
+     * LOT 6 — inject always-present locked targets for one recipient member:
+     *  A) official accounts (ACME) on networks the member SHARES with them — full
+     *     Connecter→Contacter (subscribe if not yet connected, contact after);
+     *  B) active boosters on networks the member LACKS — single Contacter spotlight.
+     * Both are `locked` (no Masquer; "Passer" still allowed) and bypass scoring/caps.
+     */
+    protected injectLockedActions(state: RunState, member: Member, taskMap: Map<string, WeeklyTask>, week: number): void {
+        const memberPlatforms = new Set<string>(
+            member.socialMedias.filter(sm => sm.isActive).map(sm => sm.platform)
+        );
+
+        const ensureTask = (): WeeklyTask => {
+            let task = taskMap.get(member.id);
+            if (!task) {
+                task = new WeeklyTask(member.id, week, state.year);
+                taskMap.set(member.id, task);
+            }
+            return task;
+        };
+        const appendTarget = (platform: string, pass: string, tp: TargetProfile): void => {
+            const task = ensureTask();
+            const key = `${platform}_${pass}`;
+            if (task.platformTasks[key]) task.platformTasks[key].targets.push(tp);
+            else task.addPlatformTask(platform as Platform, [tp], null, pass);
+        };
+
+        // A) Official accounts on SHARED networks.
+        for (const official of state.officialMembers) {
+            for (const osm of official.socialMedias) {
+                if (!osm.isActive || !memberPlatforms.has(osm.platform)) continue;
+                const connected = this.subscriptionStore.hasSubscribed(member.id, official.id, osm.platform);
+                const tp: TargetProfile = {
+                    memberSocialMediaId: osm.id,
+                    memberId: official.id,
+                    profileUrl: osm.profileUrl,
+                    action: connected ? 'contact' : 'subscription',
+                    actionCount: 1,
+                    locked: true,
+                };
+                const name = [official.firstName, official.lastName].filter(Boolean).join(' ');
+                if (name) tp.memberName = name;
+                if (official.company) tp.companyName = official.company;
+                appendTarget(osm.platform, connected ? CONTACT_PASS : CONNECT_PASS, tp);
+            }
+        }
+
+        // B) Boosters on LACKED networks (dedup: skip platforms the member is on).
+        for (const b of state.activeBoosters) {
+            if (memberPlatforms.has(b.platform) || b.memberId === member.id) continue;
+            const tp: TargetProfile = {
+                memberSocialMediaId: b.memberSocialMediaId,
+                memberId: b.memberId,
+                profileUrl: b.profileUrl,
+                action: 'contact',
+                actionCount: 1,
+                locked: true,
+                boosterId: b.id,
+            };
+            const target = state.memberLookup.get(b.memberId);
+            const name = b.label ?? (target ? [target.firstName, target.lastName].filter(Boolean).join(' ') : '');
+            if (name) tp.memberName = name;
+            if (target?.company) tp.companyName = target.company;
+            appendTarget(b.platform, CONTACT_PASS, tp);
+        }
+    }
